function adapt(input, solve, kit) {
  const [specs, ms] = input;
  const functions = specs.map((spec, index) => () => {
    kit.trace(`functions[${index}] is called`);
    const failing = spec.reject !== undefined;
    const outcome = failing ? spec.reject : spec.resolve;
    const settle = () => kit.trace(`The promise of functions[${index}] ${failing ? 'rejects' : 'resolves'} with ${JSON.stringify(outcome)}`);
    if (spec.t === 0) {
      settle();
      return failing ? Promise.reject(outcome) : Promise.resolve(outcome);
    }
    return new Promise((resolve, reject) => setTimeout(() => {
      settle();
      if (failing) reject(outcome);
      else resolve(outcome);
    }, spec.t));
  });
  const start = Date.now();
  kit.trace(`delayAll is called with ${specs.length} function${specs.length === 1 ? '' : 's'} and ms = ${ms}`);
  const delayed = solve(functions, ms);
  if (!Array.isArray(delayed) || delayed.length !== specs.length) throw new Error('delayAll must return an array with one function per entry of functions.');
  const outcomes = delayed.map((fn, index) => {
    if (typeof fn !== 'function') throw new Error('Every entry of the returned array must be a function.');
    kit.trace(`delayed[${index}] is called`);
    const promise = fn();
    if (!promise || typeof promise.then !== 'function') throw new Error('Each returned function must give back a promise.');
    return promise.then((value) => {
      kit.trace(`The promise of delayed[${index}] resolves with ${JSON.stringify(value)}`);
      return { t: Date.now() - start, status: 'fulfilled', value };
    }, (reason) => {
      const shown = reason instanceof Error ? String(reason) : reason;
      kit.trace(`The promise of delayed[${index}] rejects with ${JSON.stringify(shown)}`);
      return { t: Date.now() - start, status: 'rejected', reason: shown };
    });
  });
  return Promise.all(outcomes);
}

