function delayAll(functions, ms) {
  // The same idea with async/await: wait for the original, pause, then pass its outcome on.
  const pause = () => new Promise((resolve) => setTimeout(resolve, ms));
  return functions.map((fn) => async () => {
    let outcome;
    try {
      outcome = { ok: true, value: await fn() };
    } catch (reason) {
      outcome = { ok: false, reason };
    }
    await pause();
    if (!outcome.ok) throw outcome.reason;
    return outcome.value;
  });
}

